eventScripts.script:
if currentValue.value and not initialChange:
	frontAMR = system.tag.readBlocking(["[.]AMRNumberAssignedToStation",])[0].value
	rearAMR =  system.tag.readBlocking(["[.]pairedAMRID"])[0].value
	functionParams = {
		'function': 'AMR.Commands.sendPairAction',
		'params': {'frontAMRNumber':frontAMR,
			'rearAMRNumber': rearAMR,
			'pairAction': 1 #1 = pair AMRS
		}
	}

	#send message handler to Backend 2 to create insant action to pair the AMRs.	
	system.util.sendMessage(project = 'FactoryGatewayEvents', messageHandler = 'executeFunction',payload = functionParams,remoteServers = [GatewayConfig.getBackEnd_2()])

if currentValue.value:
	amrIDs = system.tag.readBlocking(["[.]AMRNumberAssignedToStation","[.]pairedAMRID"])
	params = {
			'function':'AMR.Commands.sendPairAction',
			'params': {
			'frontAMRNumber':amrIDs[0].value,
			'rearAMRNumber': amrIDs[1].value,
			'pairAction': 2
			}
	}

	#funciton only exists on backend 2,
	system.util.sendMessage(project = 'FactoryGatewayEvents', messageHandler= 'executeFunction',payload = params, remoteServers = [GatewayConfig.getBackEnd_2()])

tags.expression:
if(
    (
       ({[.]nextComponentID} = "" & {[.]nextItemNumber} = "" & {[.]../Control/fromIGN/componentID} = "") &
       (
          ({[.]stationType} != 1 & {[.]stationType} != 3 & {[.]stationType} != 12 & {[.]stationType} != 13) ||
          ({[.]stationType} = 3 & ({[.]../Control/Parameters.stationName} = "TW0700" || {[.]../Control/Parameters.stationName} = "TT170A" || {[.]../Control/Parameters.stationName} = "TT170B"))
       )
    )
    // station type 4 - paint load. If next componentId is blank, fire get next work order.
    // station type 4 - if material handler is in station and next component has NOT been loaded yet, keep refreshing
    || try(
         {[.]stationType} = 4 & ({[.]nextComponentID} = "" || ({[.]../AMRControl/materialInStation} & {[.]../Control/toIGN/nextComponentLoaded} = False)),
         False
       ),
    runScript("RunSchedule.getNextWorkOrder.getOrder",10000, {[.]../Control/Parameters.stationName}),
    False
)

// if station cycle is false and either next component id or next item number are not cleared, run the resetStatus function, else return False.
if(({[.]../Control/toIGN/stationCycle} = False && {[.]resetStation} = True) && ({[.]nextComponentID} != '' || {[.]nextItemNumber} != '')
, runScript("RunSchedule.getNextWorkOrder.resetStatus",0, {[.]../Control/Parameters.stationName})
, false
)

if(isAlarmActive("*" + {stationName} + "*"), True, False)
||
isAlarmActive("[TAGIO2]JLG/Jefferson City/Fleet/AMR Data/AMR_" + numberFormat({[.]../AMRControl/AMRNumberAssignedToStation},"#000") + "/*")

if({[.]stationType} =1,
tag("[Orch]JLG/Jefferson City/Jefferson City Assembly/Jefferson City Final Assembly Processes/" + {[.]siteNumber} + "/JaMES/" + {[.]serialNumber} + "/" + {[.]departmentNumber} + "/" + {[.]workCenterNumber} + "/completed"),
tag("[Orch]JLG/Jefferson City/Jefferson City Assembly/Jefferson City Final Assembly Processes/" + {[.]siteNumber} + "/JaMES/" + {[.]nwgWorkOrderNumber} + "/" + {[.]departmentNumber} + "/" + {[.]workCenterNumber} + "/completed"))

