	# When shift active changes state, update start of shift checklist tags and dataset accordingly
    basePath = str(tagPath).rsplit("/", 1)[0]
    area = system.tag.readBlocking([basePath + "/Parameters.Area"])[0].value

    gw = GatewayConfig.getFrontEnd_1()

    payload = {
        'function': 'SOSChecklist.Internal.refreshSOSEntries',
        'params': {'area': area}
    }

    system.util.sendRequest(project='FactoryControl', messageHandler='executeFunction', payload=payload, remoteServer=gw)


    # When the shift has ended, reset the start of shift checklistr report completetion tags if high

    if previousValue is not None and not initialChange: 
    	if previousValue.value == True and currentValue.value == False: 
    		currentShiftEndTime = system.tag.readBlocking(["[.]currentShiftEnd"])[0].value 
    		if currentShiftEndTime is None: 
    			system.tag.writeBlocking(["[.]startOfShiftChecklist/sosChecklistAreaReportEmailSent"], False)

